package vmcompat;
import java.nio.*;import org.lwjgl.*;import org.lwjgl.glfw.*;import org.lwjgl.opengl.*;
/** Independent contexts can reuse program names without losing another pool. */
public final class PackingContextTests {
 static void check(boolean b,String s){if(!b)throw new AssertionError(s+" GL="+GL11.glGetError());}
 static int[] setup(int value){Context.capabilities();GL11.glViewport(0,0,16,16);int p=StorageBuffersTests.program("#version 330\nuniform sampler2D images[16];uniform sampler2D a;uniform sampler2D b;out vec4 c;void main(){vec4 sum=vec4(0);for(int i=0;i<16;i++)sum+=texture(images[i],vec2(.5));c=(sum+texture(a,vec2(.5))+texture(b,vec2(.5)))/18.;}");Shaders.glUseProgram(p);int t=Textures.glCreateTextures(GL11.GL_TEXTURE_2D);Textures.glTextureStorage2D(t,1,GL11.GL_RGBA8,1,1);Textures.glTextureParameteri(t,GL11.GL_TEXTURE_MIN_FILTER,GL11.GL_NEAREST);Textures.glTextureParameteri(t,GL11.GL_TEXTURE_MAG_FILTER,GL11.GL_NEAREST);Textures.glTextureSubImage2D(t,0,0,0,1,1,GL11.GL_RGBA,GL11.GL_UNSIGNED_BYTE,BufferUtils.createByteBuffer(4).put(new byte[]{(byte)value,0,0,(byte)255}).flip());Samplers.glActiveTexture(GL13.GL_TEXTURE0);Samplers.glBindTexture(GL11.GL_TEXTURE_2D,t);for(int i=0;i<16;i++)Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"images["+i+"]"),0);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"a"),0);Samplers.glUniform1i(Shaders.glGetUniformLocation(p,"b"),0);int vao=GL30.glGenVertexArrays();Draws.glBindVertexArray(vao);return new int[]{p,t,vao};}
 static void pixel(int[] state,int expected){Shaders.glUseProgram(state[0]);Draws.glBindVertexArray(state[2]);Draws.glDrawArrays(GL11.GL_TRIANGLES,0,3);FloatBuffer b=BufferUtils.createFloatBuffer(4);GL11.glReadPixels(8,8,1,1,GL11.GL_RGBA,GL11.GL_FLOAT,b);check(Math.abs(b.get(0)-expected/255f)<.008,"context pixel");}
 public static void main(String[] a){check(GLFW.glfwInit(),"init");GLFW.glfwWindowHint(GLFW.GLFW_VISIBLE,0);long one=Context.createWindow(16,16,"Packing context A",0,0);Context.makeCurrent(one);int[] first=setup(64);pixel(first,64);long memory=Packing.memoryStats()[0];long two=Context.createWindow(16,16,"Packing context B",0,0);Context.makeCurrent(two);int[] second=setup(192);pixel(second,192);check(first[0]==second[0],"exercise duplicate native program IDs");check(Packing.memoryStats()[0]>memory,"separate owned allocations");Context.destroyWindow(two);Context.makeCurrent(one);Context.capabilities();pixel(first,64);check(Packing.memoryStats()[0]==memory,"other context cleanup preserves first pool");Shaders.glDeleteProgram(first[0]);Textures.glDeleteTextures(first[1]);Context.destroyWindow(one);GLFW.glfwTerminate();check(Packing.memoryStats()[0]==0,"all contexts released");System.out.println("PASS independent contexts with reused IDs, image and cleanup");}
}
